if(EditorApplication.isPlaying)throw new System.Exception("Edit required");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var meshes=all.Where(t=>t.name=="05_Planter_Recessed_Soil"||t.name=="CM_PairedWindowBay02_FlowerBox").SelectMany(t=>t.GetComponentsInChildren<MeshFilter>(true)).Distinct().Where(m=>m.gameObject.activeInHierarchy).ToArray();var temp=new System.Collections.Generic.List<MeshCollider>();var rows=new System.Collections.Generic.List<object>();try{foreach(var mf in meshes){var g=new GameObject("Temporary soil datum audit");g.transform.SetPositionAndRotation(mf.transform.position,mf.transform.rotation);g.transform.localScale=mf.transform.lossyScale;var c=g.AddComponent<MeshCollider>();c.sharedMesh=mf.sharedMesh;temp.Add(c);}foreach(var t in all.Where(t=>t.name.StartsWith("Window planting -"))){var ray=new Ray(t.position+Vector3.up*.35f,Vector3.down);var hs=new System.Collections.Generic.List<RaycastHit>();foreach(var c in temp)if(c.Raycast(ray,out var h,.7f))hs.Add(h);if(hs.Count==0)throw new System.Exception("No planter soil: "+t.name);var hit=hs.OrderBy(v=>v.distance).First();var old=t.position;float delta=hit.point.y+.003f-old.y;if(Mathf.Abs(delta)>.001f){t.position=new Vector3(old.x,hit.point.y+.003f,old.z);PrefabUtility.RecordPrefabInstancePropertyModifications(t);}rows.Add(new{t.name,old=old.ToString("F4"),current=t.position.ToString("F4"),correction=delta,gap=t.position.y-hit.point.y});}}finally{foreach(var c in temp)UnityEngine.Object.DestroyImmediate(c.gameObject);}System.IO.File.WriteAllText("ArtSource/Blender/Interiors/CrookedMortar/Illustrated04/WindowPlantingDatums.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);return rows;
